<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { detallarSesion, eliminarSesion, finalizarSesion, guardarSesion, listarSesiones, type Sesion, type SesionPayload } from '../services/sesiones'
const filters=reactive({criterio:'',desde:'',hasta:'',page:1}),items=ref<Sesion[]>([]),pagination=reactive({current:1,last:1,total:0}),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),detail=ref<Sesion|null>(null),agendaText=ref('')
const form=reactive<SesionPayload>({numeracion:'',tipo:'o',modalidad:'presencial',url_enlace:'',primera_convocatoria:'',segunda_convocatoria:'',fecha_sesion:'',fecha_limite_carga_archivos:'',puntos_agenda:[]})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarSesiones(filters);items.value=r.data;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total})}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudieron cargar las sesiones.'}finally{loading.value=false}}
function clear(){Object.assign(filters,{criterio:'',desde:'',hasta:'',page:1});void load()}
function resetForm(){Object.assign(form,{numeracion:'',tipo:'o',modalidad:'presencial',url_enlace:'',primera_convocatoria:'',segunda_convocatoria:'',fecha_sesion:'',fecha_limite_carga_archivos:'',puntos_agenda:[]});agendaText.value=''}
function openCreate(){editing.value=null;resetForm();modal.value=true}
function openEdit(i:Sesion){editing.value=i.id;Object.assign(form,{numeracion:i.numeracion,tipo:i.tipo,modalidad:i.modalidad,url_enlace:i.url_enlace||'',primera_convocatoria:i.primera_convocatoria?.slice(0,5)||'',segunda_convocatoria:i.segunda_convocatoria?.slice(0,5)||'',fecha_sesion:i.fecha_sesion?.slice(0,10)||'',fecha_limite_carga_archivos:i.fecha_limite_carga_archivos?.slice(0,10)||'',puntos_agenda:i.agenda.map(a=>a.punto_agenda)});agendaText.value='';modal.value=true}
function addAgenda(){const text=agendaText.value.trim();if(text.length<5){error.value='El punto de agenda debe tener al menos 5 caracteres.';return}form.puntos_agenda.push(text);agendaText.value='';error.value=''}
function validate(){if(!form.numeracion.trim()||!form.fecha_sesion||!form.primera_convocatoria||!form.fecha_limite_carga_archivos)return'Complete número, fecha, primera convocatoria y fecha límite.';if(form.modalidad==='virtual'&&!form.url_enlace.trim())return'Ingrese el enlace para la sesión virtual.';if(form.fecha_limite_carga_archivos>form.fecha_sesion)return'La fecha límite no puede superar la fecha de la sesión.';if(!form.puntos_agenda.length)return'Agregue al menos un punto de agenda.';return''}
async function save(){error.value=validate();if(error.value)return;saving.value=true;try{await guardarSesion(editing.value,{...form});success.value=editing.value?'Sesión actualizada correctamente.':'Sesión agendada correctamente.';modal.value=false;await load(editing.value?pagination.current:1)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo guardar la sesión.'}finally{saving.value=false}}
async function show(i:Sesion){loading.value=true;try{detail.value=await detallarSesion(i.id)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo cargar el detalle.'}finally{loading.value=false}}
function canDelete(i:Sesion){return !i.finalizado&&!i.agenda.some(a=>a.tiene_archivos)}
async function remove(i:Sesion){if(!confirm(`¿Eliminar la sesión ${i.numeracion}?`))return;try{await eliminarSesion(i.id);success.value='Sesión eliminada.';await load(pagination.current)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo eliminar.'}}
async function finish(i:Sesion){if(!confirm(`¿Finalizar la sesión ${i.numeracion}?`))return;try{await finalizarSesion(i.id);success.value='Sesión finalizada correctamente.';await load(pagination.current)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo finalizar.'}}
function tipo(i:Sesion){return i.tipo==='o'?'Ordinaria':i.tipo==='e'?'Extraordinaria':'Universal'}
function date(v?:string|null){if(!v)return'—';const d=new Date(`${v.slice(0,10)}T00:00:00`);return new Intl.DateTimeFormat('es-PE',{dateStyle:'long'}).format(d)}
onMounted(()=>load())
</script>
<template><div class="sessions"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/institucional">Institucional</RouterLink> / Directorio / Sesiones</nav><header class="hero"><div class="mark">AU</div><div><small>Directorio</small><h1>Sesiones</h1><p>Programa y administra las sesiones, convocatorias y puntos de agenda.</p></div><strong>{{pagination.total}} sesiones</strong><button @click="openCreate">+ Agendar sesión</button></header><div v-if="success" class="flash">✓ {{success}}<button @click="success=''">×</button></div><div v-if="error" class="flash error">{{error}}<button @click="error=''">×</button></div><form class="filters" @submit.prevent="load()"><label><span>Criterio</span><input v-model.trim="filters.criterio" placeholder="Número, tipo o punto de agenda"></label><label><span>Desde</span><input v-model="filters.desde" type="date"></label><label><span>Hasta</span><input v-model="filters.hasta" type="date"></label><button>Buscar</button><button type="button" class="clear" @click="clear">Limpiar</button></form><div v-if="loading" class="notice">Cargando sesiones…</div><div v-else-if="!items.length" class="notice"><b>No se encontraron sesiones</b><span>Modifica los filtros o agenda una nueva sesión.</span></div><section v-else class="cards"><article v-for="i in items" :key="i.id" :class="{finished:i.finalizado}"><header><div class="calendar"><b>{{new Date(`${i.fecha_sesion.slice(0,10)}T00:00:00`).getDate()}}</b><span>{{new Intl.DateTimeFormat('es-PE',{month:'short'}).format(new Date(`${i.fecha_sesion.slice(0,10)}T00:00:00`))}}</span></div><div><small>Sesión {{tipo(i)}}</small><h2>N.° {{i.numeracion}}</h2><p>{{date(i.fecha_sesion)}}</p></div><em>{{i.finalizado?'Finalizada':'Programada'}}</em></header><div class="body"><dl><div><dt>Modalidad</dt><dd>{{i.modalidad}}</dd></div><div><dt>Primera convocatoria</dt><dd>{{i.primera_convocatoria?.slice(0,5)}}</dd></div><div><dt>Segunda convocatoria</dt><dd>{{i.segunda_convocatoria?.slice(0,5)||'—'}}</dd></div><div><dt>Límite de archivos</dt><dd>{{date(i.fecha_limite_carga_archivos)}}</dd></div></dl><div class="agenda"><b>Agenda ({{i.agenda.length}})</b><ol><li v-for="a in i.agenda.slice(0,3)" :key="a.id">{{a.punto_agenda}}</li></ol><small v-if="i.agenda.length>3">+ {{i.agenda.length-3}} puntos adicionales</small></div></div><footer><button @click="show(i)">Ver detalle</button><button v-if="!i.finalizado" class="edit" @click="openEdit(i)">Editar</button><button v-if="!i.finalizado" class="finish" @click="finish(i)">Finalizar</button><button v-if="canDelete(i)" class="delete" @click="remove(i)">Eliminar</button></footer></article></section><footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><section class="modal"><header><div><small>Directorio</small><h2>{{editing?'Modificar':'Agendar'}} sesión</h2></div><button @click="modal=false">×</button></header><form @submit.prevent="save"><div class="grid"><label><span>Número de sesión *</span><input v-model.trim="form.numeracion"></label><label><span>Tipo *</span><select v-model="form.tipo"><option value="o">Ordinaria</option><option value="e">Extraordinaria</option><option value="u">Universal</option></select></label><label><span>Modalidad *</span><select v-model="form.modalidad"><option value="presencial">Presencial</option><option value="virtual">Virtual</option></select></label><label v-if="form.modalidad==='virtual'"><span>Enlace virtual *</span><input v-model.trim="form.url_enlace" type="url"></label><label><span>Primera convocatoria *</span><input v-model="form.primera_convocatoria" type="time"></label><label><span>Segunda convocatoria</span><input v-model="form.segunda_convocatoria" type="time"></label><label><span>Fecha de sesión *</span><input v-model="form.fecha_sesion" type="date"></label><label><span>Límite para archivos *</span><input v-model="form.fecha_limite_carga_archivos" type="date"></label></div><section class="agenda-editor"><h3>Puntos de agenda</h3><div><input v-model.trim="agendaText" placeholder="Nuevo punto de agenda" @keydown.enter.prevent="addAgenda"><button type="button" @click="addAgenda">Agregar</button></div><ol><li v-for="(a,index) in form.puntos_agenda" :key="index"><span>{{a}}</span><button type="button" @click="form.puntos_agenda.splice(index,1)">×</button></li></ol></section><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar sesión':'Agendar sesión'}}</button></footer></form></section></div><div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>Sesión {{tipo(detail)}}</small><h2>N.° {{detail.numeracion}}</h2><p>{{date(detail.fecha_sesion)}} · {{detail.modalidad}}</p></div><button @click="detail=null">×</button></header><div class="detail-body"><section><h3>Convocatoria</h3><dl><div><dt>Primera</dt><dd>{{detail.primera_convocatoria?.slice(0,5)}}</dd></div><div><dt>Segunda</dt><dd>{{detail.segunda_convocatoria?.slice(0,5)||'—'}}</dd></div><div><dt>Enlace</dt><dd>{{detail.url_enlace||'—'}}</dd></div><div><dt>Estado</dt><dd>{{detail.finalizado?'Finalizada':'Programada'}}</dd></div></dl></section><section><h3>Directores participantes</h3><ul><li v-for="d in detail.directores" :key="d.id"><b>{{d.persona.nombre_completo||d.persona.nombre}}</b><span>{{d.cargo==='p'?'Presidente':'Miembro'}}</span></li></ul></section><section class="wide"><h3>Agenda</h3><ol><li v-for="a in detail.agenda" :key="a.id"><span>{{a.punto_agenda}}</span><em>{{a.archivos_count||0}} archivos · {{a.acciones_count||0}} acciones</em></li></ol></section><section v-if="detail.actas?.length" class="wide"><h3>Actas</h3><ul><li v-for="a in detail.actas" :key="a.id"><b>{{a.archivo}}</b><span>{{a.usuario?.nombre||''}}</span></li></ul></section></div></section></div></div></template>
<style scoped>
.sessions{--accent:#7257c8;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.62rem;font-weight:700;text-transform:uppercase}.hero h1{margin:2px 0;font-size:1.38rem}.hero p{margin:0;color:#7d898f;font-size:.72rem}.hero>strong{margin-left:auto;font-size:.64rem}.hero>button,.filters button,.pagination button,.cards footer button,.modal footer button,.agenda-editor>div button{padding:8px 12px;border:1px solid var(--accent);border-radius:7px;color:#fff;background:var(--accent);font-size:.62rem}.flash{margin-top:14px;padding:11px;display:flex;border:1px solid #b9dfce;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.68rem}.flash.error{color:#a13f43;border-color:#efcaca;background:#fff4f4}.flash button{margin-left:auto;border:0;background:none}.filters{margin:16px 0;padding:18px;display:grid;grid-template-columns:1.4fr 1fr 1fr auto auto;align-items:end;gap:8px;border:1px solid #e2e7ea;border-radius:11px;background:#fff}label span{display:block;margin-bottom:6px;color:#66737a;font-size:.63rem}input,select{width:100%;height:40px;padding:0 10px;border:1px solid #dae2e6;border-radius:7px;background:#fff;font:inherit;font-size:.67rem}.clear{color:#68757c!important;border-color:#d5dee2!important;background:#fff!important}.notice{padding:45px;display:flex;align-items:center;flex-direction:column;gap:6px;text-align:center;border:1px dashed #cbd6dc;border-radius:10px;background:#fff;font-size:.69rem}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.cards article{overflow:hidden;border:1px solid #e1ddef;border-top:3px solid var(--accent);border-radius:11px;background:#fff}.cards article.finished{border-top-color:#7e898f}.cards article>header{padding:14px;display:flex;align-items:center;gap:10px;border-bottom:1px solid #eeebf4}.calendar{width:43px;height:45px;display:flex;align-items:center;justify-content:center;flex-direction:column;border-radius:8px;color:#fff;background:var(--accent)}.calendar b{font-size:.88rem}.calendar span{font-size:.52rem;text-transform:uppercase}.cards h2{margin:2px 0;font-size:.78rem}.cards header small,.cards header p{margin:0;color:#89959b;font-size:.55rem}.cards header em{margin-left:auto;padding:4px 6px;border-radius:12px;color:#5c469f;background:#eeeafa;font-size:.52rem;font-style:normal}.finished header em{color:#626d72;background:#e9edef}.body{padding:14px}.body dl{margin:0}.body dl>div{padding:5px 0;display:flex;justify-content:space-between;border-bottom:1px solid #f0eef4;font-size:.59rem}.body dd{margin:0}.agenda{margin-top:10px}.agenda b,.agenda li,.agenda small{font-size:.58rem}.agenda ol{margin:6px 0;padding-left:18px}.agenda small{color:#89959b}.cards article>footer{padding:0 14px 14px;display:flex;flex-wrap:wrap;gap:5px}.cards footer button{flex:1}.cards .edit{color:#705412;border-color:#efd18c;background:#ffefca}.cards .finish{background:#278763;border-color:#278763}.cards .delete{background:#bd5050;border-color:#bd5050}.pagination{padding:18px;display:flex;justify-content:center;align-items:center;gap:12px;font-size:.64rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,720px);max-height:calc(100vh - 40px);overflow:auto;border-radius:12px;background:#fff}.modal>header{padding:18px 20px;display:flex;border-bottom:1px solid #e5eaed}.modal h2{margin:2px 0;font-size:1rem}.modal>header p{margin:2px 0;font-size:.62rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal>form{padding:20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.agenda-editor{margin-top:18px}.agenda-editor h3,.detail-body h3{font-size:.72rem}.agenda-editor>div{display:flex;gap:6px}.agenda-editor ol{padding-left:22px}.agenda-editor li{padding:5px;font-size:.62rem}.agenda-editor li span{display:inline-block;width:calc(100% - 30px)}.agenda-editor li button{float:right;border:0;color:#a13f43;background:none}.modal form>footer{display:flex;justify-content:flex-end;gap:7px}.detail{max-width:780px}.detail-body{padding:20px;display:grid;grid-template-columns:1fr 1fr;gap:14px}.detail-body section{padding:13px;border:1px solid #e4e8eb;border-radius:8px}.detail-body .wide{grid-column:1/-1}.detail-body dl{margin:0}.detail-body dl>div,.detail-body li{padding:6px 0;display:flex;justify-content:space-between;border-top:1px solid #edf0f2;font-size:.61rem}.detail-body dd{margin:0}.detail-body ul,.detail-body ol{margin:0;padding-left:18px}.detail-body li b,.detail-body li span{font-size:.6rem}.detail-body li em{color:#89959b;font-size:.55rem;font-style:normal}@media(max-width:1000px){.cards{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr 1fr}}@media(max-width:620px){.hero{flex-wrap:wrap}.hero>strong{margin:0}.hero>button{width:100%}.cards,.filters,.grid,.detail-body{grid-template-columns:1fr}.detail-body .wide{grid-column:auto}}
</style>
